// P3 S3 Part B — astro.ts golden cross-check + direct unit anchors.
// Spec: my_plans/marvin/p3/S3_sgp4_provider_astro.md "Part B".
//
// astro-golden.json is generated by packages/frontend/scripts/gen-astro-golden.ts
// via the REAL client path (getSunDirection/getObserverScenePosition + the
// live-source scene->TEME inverse swap). This test IS the "copied, not forked"
// guarantee, made executable.

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';
import { describe, it } from 'node:test';
import { getGAST, sunDirTeme, observerTeme } from '../../src/analytic/astro.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const GOLDEN_PATH = resolve(__dirname, '../../src/analytic/astro-golden.json');

interface GoldenRow {
  iso: string;
  tMs: number;
  gast: number;
  sun: { x: number; y: number; z: number };
  observers: { latDeg: number; lonDeg: number; altKm: number; teme: { x: number; y: number; z: number } }[];
}

const golden = JSON.parse(readFileSync(GOLDEN_PATH, 'utf8')) as { rows: GoldenRow[] };

function assertCloseRel(actual: number, expected: number, msg: string, relTol = 1e-9): void {
  const diff = Math.abs(actual - expected);
  // Near-zero expected values (e.g. z=0 at the equator) need an absolute floor —
  // a pure relative tolerance is meaningless against zero.
  const tol = Math.max(relTol, relTol * Math.abs(expected));
  assert.ok(diff <= tol, `${msg}: expected ${expected}, got ${actual} (diff ${diff}, tol ${tol})`);
}

describe('astro.ts — golden cross-check against the real client path', () => {
  it('fixture has rows (else run gen-astro-golden.ts)', () => {
    assert.ok(golden.rows.length > 0, 'astro-golden.json must have rows — run gen-astro-golden.ts');
  });

  for (const row of golden.rows) {
    describe(`instant ${row.iso}`, () => {
      it('getGAST matches', () => {
        assertCloseRel(getGAST(row.tMs), row.gast, 'gast');
      });

      it('sunDirTeme matches', () => {
        const s = sunDirTeme(row.tMs);
        assertCloseRel(s.x, row.sun.x, 'sun.x');
        assertCloseRel(s.y, row.sun.y, 'sun.y');
        assertCloseRel(s.z, row.sun.z, 'sun.z');
      });

      for (const obs of row.observers) {
        it(`observerTeme matches (lat=${obs.latDeg}, lon=${obs.lonDeg}, alt=${obs.altKm})`, () => {
          const t = observerTeme(obs.latDeg, obs.lonDeg, obs.altKm, row.tMs);
          assertCloseRel(t.x, obs.teme.x, 'observer.x');
          assertCloseRel(t.y, obs.teme.y, 'observer.y');
          assertCloseRel(t.z, obs.teme.z, 'observer.z');
        });
      }
    });
  }
});

describe('astro.ts — direct unit anchors (independent of the client)', () => {
  it('GAST at the J2000.0 epoch is the known value (~280.4606°, in radians)', () => {
    const j2000Ms = Date.parse('2000-01-01T12:00:00Z');
    const expectedRad = 280.46061837 * (Math.PI / 180);
    assertCloseRel(getGAST(j2000Ms), expectedRad, 'GAST @ J2000.0', 1e-6);
  });

  it('sun direction is near (1,0,0) at the March 2026 equinox instant', () => {
    const equinoxMs = Date.parse('2026-03-20T09:00:00Z');
    const s = sunDirTeme(equinoxMs);
    assert.ok(Math.abs(s.x - 1) < 0.01, `sun.x should be near 1, got ${s.x}`);
    assert.ok(Math.abs(s.y) < 0.01, `sun.y should be near 0, got ${s.y}`);
    assert.ok(Math.abs(s.z) < 0.01, `sun.z should be near 0, got ${s.z}`);
  });

  it('observer at lat=0, lon=0 has |r| = 1.0 ER and rotates with GAST', () => {
    const t1 = Date.parse('2026-01-01T00:00:00Z');
    const t2 = t1 + 6 * 3600_000; // 6h later — GAST rotates ~90°

    const o1 = observerTeme(0, 0, 0, t1);
    const r1 = Math.sqrt(o1.x * o1.x + o1.y * o1.y + o1.z * o1.z);
    assertCloseRel(r1, 1.0, '|r| at t1', 1e-9);
    assert.equal(o1.z, 0); // equator stays in the equatorial plane

    const o2 = observerTeme(0, 0, 0, t2);
    const r2 = Math.sqrt(o2.x * o2.x + o2.y * o2.y + o2.z * o2.z);
    assertCloseRel(r2, 1.0, '|r| at t2', 1e-9);
    // A fixed geodetic point traces a different equatorial direction 6h later —
    // the position must have rotated, not stayed put.
    assert.ok(Math.abs(o1.x - o2.x) > 0.1 || Math.abs(o1.y - o2.y) > 0.1);
  });
});
